import{_ as t,o,c as a,a2 as d}from"./chunks/framework.CNDaxUod.js";const m=JSON.parse('{"title":"Roles and permissions","description":"","frontmatter":{},"headers":[],"relativePath":"guide/roles.md","filePath":"guide/roles.md"}'),s={name:"guide/roles.md"};function r(n,e,i,l,p,c){return o(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="roles-and-permissions" tabindex="-1">Roles and permissions <a class="header-anchor" href="#roles-and-permissions" aria-label="Permalink to &quot;Roles and permissions&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Role</th><th>How you get it</th><th>What it grants</th></tr></thead><tbody><tr><td>Operator</td><td>Holds the operator token (<code>OPERATOR_TOKEN</code>)</td><td>Everything, including workspace settings, while token sign-in is on</td></tr><tr><td>Workspace admin</td><td>A Google Workspace super or delegated admin (through the <a href="./directory.html">Directory</a>), or in the SAML admin group</td><td>The full console: every standup, workspace settings, deleting archived standups</td></tr><tr><td>Manager (standup admin)</td><td>Ran <code>setup</code>, created the standup in the web app, or was granted <code>admin @user</code></td><td>Configure that standup from Chat or the web app; manage the schedules and time-off requests of people on it</td></tr><tr><td>Participant</td><td>On the standup&#39;s roster: picked in the People grid, <code>add @user</code>, or a member of the Google Group it follows</td><td>Answer, edit, skip, DM self-service, their own page at <code>/app/me</code></td></tr><tr><td>Everyone in the space</td><td>—</td><td><code>status</code>, <code>trends</code>, <code>blockers</code>, <code>blocker</code>, polls, <code>help</code>, and <code>setup</code></td></tr></tbody></table><p>Notes:</p><ul><li>A standup always keeps at least one admin; removing the last is refused.</li><li>A standup created with no admins (for example from a script with the operator token) is open to configuration by anyone in its space. Name an admin when creating on someone&#39;s behalf.</li><li>The web app and the <a href="./api.html">JSON API</a> share one authorisation model. MCP tools act as the token&#39;s owner and see exactly what that person sees (<a href="./mcp.html">Claude Code and MCP</a>).</li><li>Who may mark someone away is set per standup by its <a href="./schedules.html#who-can-change-what-the-time-off-policy">time-off policy</a>.</li></ul>',4)])])}const u=t(s,[["render",r]]);export{m as __pageData,u as default};
